import { Body, Controller, Get, Injectable, Module, NotFoundException, Param, ParseUUIDPipe, Post, Query, Req, UnprocessableEntityException } from '@nestjs/common';
import { ApiBearerAuth, ApiProperty, ApiPropertyOptional, ApiTags } from '@nestjs/swagger';
import { IsDateString, IsEmail, IsOptional, IsString, IsUUID, Length, Matches } from 'class-validator';
import { Database } from '../database.module';
import { Roles, TenantRequest } from '../auth/auth.module';
import { PageDto, paginated } from '../common/page.dto';

export class CreateEmployeeDto {
 @ApiProperty() @IsString() @Length(1,30) employeeNo: string;
 @ApiProperty() @IsString() @Length(1,200) name: string;
 @ApiPropertyOptional() @IsOptional() @IsEmail() email?: string;
 @ApiProperty({example:'2026-10-01'}) @IsDateString({strict:true}) @Matches(/^\d{4}-\d{2}-\d{2}$/) joinedDate: string;
 @ApiPropertyOptional() @IsOptional() @IsUUID() departmentId?: string;
 @ApiPropertyOptional() @IsOptional() @IsUUID() positionId?: string;
}
@Injectable()
export class EmployeesService {
 constructor(private db: Database) {}
 async list(companyId: string, q: PageDto) {
  const where = {companyId,...(q.search ? {name:{contains:q.search,mode:'insensitive' as const}} : {})};
  const [data,total] = await this.db.$transaction([
   this.db.employee.findMany({where,orderBy:[{name:'asc'},{id:'asc'}],skip:(q.page-1)*q.pageSize,take:q.pageSize}),
   this.db.employee.count({where}),
  ]);
  return paginated(data,total,q);
 }
 async get(companyId: string, id: string) {
  const data = await this.db.employee.findUnique({where:{companyId_id:{companyId,id}}});
  if (!data) throw new NotFoundException();
  return {data};
 }
 async create(companyId: string, dto: CreateEmployeeDto) {
  return this.db.$transaction(async tx => {
   if (dto.departmentId && !await tx.department.findFirst({where:{id:dto.departmentId,companyId,active:true}})) throw new NotFoundException('Department not found.');
   if (dto.positionId) {
    const position = await tx.position.findFirst({where:{id:dto.positionId,companyId,active:true}});
    if (!position) throw new NotFoundException('Position not found.');
    if (position.departmentId !== dto.departmentId) throw new UnprocessableEntityException('Position must belong to the selected department.');
   }
   return {data:await tx.employee.create({data:{...dto,companyId,joinedDate:new Date(dto.joinedDate+'T00:00:00.000Z')}})};
  });
 }
}
@ApiBearerAuth() @ApiTags('employees') @Roles('OWNER','HR') @Controller('employees')
export class EmployeesController {
 constructor(private service: EmployeesService) {}
 @Get() list(@Req() req: TenantRequest,@Query() q: PageDto) { return this.service.list(req.membership.companyId,q); }
 @Get(':id') get(@Req() req: TenantRequest,@Param('id',ParseUUIDPipe) id: string) { return this.service.get(req.membership.companyId,id); }
 @Post() create(@Req() req: TenantRequest,@Body() dto: CreateEmployeeDto) { return this.service.create(req.membership.companyId,dto); }
}
@Module({controllers:[EmployeesController],providers:[EmployeesService]})
export class EmployeesModule {}

